		ArbitraryLengthPath path = new ArbitraryLengthPath(Scope.DEFAULT_CONTEXTS, start, step, end, minimumLength);
		QueryBindingSet supplied = new QueryBindingSet();
		supplied.setBinding("blocked", null);
		supplied.setBinding("tag", VF.createLiteral("caller"));
