	@Test
	void exactFrameCopyKeepsGraphProvenanceAndExplicitNullsWithoutSharingMutableState() {
		QueryBindingSet caller = new QueryBindingSet();
		GraphFrameBindings.supply(caller, "g", node(0));
		caller.setBinding("blocked", null);
		GraphFrameBindings.markSiblingInputCleared(caller, 7, "x");
		BindingSetQueryEvaluationContext context = new BindingSetQueryEvaluationContext(
				new QueryEvaluationContext.Minimal(null));

		var row = context.createBindingSet(caller);
		assertThat(context.getValue("g").apply(row)).isEqualTo(node(0));
		assertThat(row.hasBinding("blocked")).isTrue();
		assertThat(context.getValue("blocked").apply(row)).isNull();
		assertThat(GraphFrameBindings.isSupplied(row, "g")).isTrue();
		assertThat(GraphFrameBindings.isSiblingInputCleared(row, 7, "x")).isTrue();
		row.setBinding("g", node(1));
		row.setBinding("x", node(1));
		assertThat(GraphFrameBindings.isSupplied(row, "g")).isFalse();
		assertThat(GraphFrameBindings.isSiblingInputCleared(row, 7, "x")).isFalse();
		assertThat(caller.getValue("g")).isEqualTo(node(0));
		assertThat(GraphFrameBindings.isSupplied(caller, "g")).isTrue();
		assertThat(GraphFrameBindings.isSiblingInputCleared(caller, 7, "x")).isTrue();
	}

	@Test
	void flexibleContextCopyHonorsQueryBindingSetSubclassGetters() {
		Value value = VF.createLiteral("visible through the binding interface");
		BindingSet source = new VirtualBindingSet("virtual", value);
		BindingSetQueryEvaluationContext context = new BindingSetQueryEvaluationContext(
				new QueryEvaluationContext.Minimal(null));

		var copy = context.createBindingSet(source);

		assertThat(copy).isNotSameAs(source);
		assertThat(copy.getBindingNames()).containsExactly("virtual");
		assertThat(copy.getValue("virtual")).isEqualTo(value);
		copy.setBinding("virtual", VF.createLiteral("changed copy"));
		assertThat(source.getValue("virtual")).isEqualTo(value);
	}

